import{_ as l,a0 as i,w as p,s as d,ao as n,I as o,a1 as s,A as a,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"如何在 KDE Plasma 桌面進行屏幕共享 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 KDE Plasma 桌面進行屏幕共享 | LCTT (202203) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 KDE Plasma 桌面進行屏幕共享 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 KDE Plasma 桌面進行屏幕共享 | LCTT (202203) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202203/20220225 How to screen share with the Linux KDE Plasma Desktop","title":"如何在 KDE Plasma 桌面進行屏幕共享","tag":"202203","desc":""},"relativePath":"202203/20220225 How to screen share with the Linux KDE Plasma Desktop.md","filePath":"[post].md"}'),m={name:"202203/20220225 How to screen share with the Linux KDE Plasma Desktop.md"};function u(f,t,k,g,h,b){const r=i("Link");return p(),d("div",null,[t[19]||(t[19]=n('<h1 id="如何在-kde-plasma-桌面進行屏幕共享" tabindex="-1">如何在 KDE Plasma 桌面進行屏幕共享 <a class="header-anchor" href="#如何在-kde-plasma-桌面進行屏幕共享" aria-label="Permalink to “如何在 KDE Plasma 桌面進行屏幕共享”">​</a></h1><blockquote><p>krfb 和 krdc 的組合是使遠程 Linux 支持變得無挫折感的寶貴工具。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202203/06/102407oi1sz113151dd5bw.jpg" alt=""></p><p>如果你曾經做過專業的或出於家庭義務的遠程支持，在待命支持時，解決問題只是第二步，更重要的是可見用户屏幕上的實際內容。有多少次你描述了複雜的桌面任務，後來才發現你的用户甚至還沒有打開他們的電腦？支持是重要的，但挫折感是真實的，對於需要支持的人和慷慨地試圖提供支持的人來説，這都是一種共同的經歷。我相信，作為學習新技能的一種方式，人們自己執行任務是很重要的，但也有一種説法是觀察專家應該如何做。這就是屏幕共享的作用，KDE Plasma 桌面已經內置了它。</p><h3 id="網絡安全" tabindex="-1">網絡安全 <a class="header-anchor" href="#網絡安全" aria-label="Permalink to “網絡安全”">​</a></h3><p>Plasma 桌面使用點對點的邀請模式進行屏幕共享。用户啓動一個應用，啓動一個虛擬網絡連接（VNC）服務器，這時，支持人員就可以遠程查看甚至控制計算機。如果這聽起來像是潛在的不安全，那是因為它可能就是，但有防火牆的干預。如果你是一個與你不在同一網絡上的人的支持人員，那麼你必須在屏幕共享工作之前建立一個從你的網絡到你的用户的網絡的安全通道。理想情況下，你會在緊急情況發生前完成這項工作。</p>',6)),o("ol",null,[o("li",null,[s(r,{href:"https://opensource.com/article/20/9/firewall"},{default:a(()=>[...t[0]||(t[0]=[e("配置用户的路由器",-1)])]),_:1}),t[1]||(t[1]=e("，將 VNC 端口（默認為 5900，但你可以使用任何你喜歡的端口）路由到他們的計算機。",-1))]),o("li",null,[s(r,{href:"https://opensource.com/article/19/7/make-linux-stronger-firewalls"},{default:a(()=>[...t[2]||(t[2]=[e("在用户的本地防火牆中打開一個服務",-1)])]),_:1}),t[3]||(t[3]=e("，允許 VNC 流量（在你在第一步中指定的端口）。",-1))])]),t[20]||(t[20]=n('<h3 id="遠程邀請" tabindex="-1">遠程邀請 <a class="header-anchor" href="#遠程邀請" aria-label="Permalink to “遠程邀請”">​</a></h3><p>為了啓動屏幕共享會話，用户必須啓動 <strong>krfb</strong>（表示 “KDE remote frame buffer”）應用。這將啓動一個 VNC 服務器，並創建一個臨時密碼。</p><p><img src="https://opensource.com/sites/default/files/kde-krfb.jpg" alt="krfb" title="krfb"></p><p><strong>krfb</strong> 使用的默認端口是 5900，但如果你需要，可以在 <strong>krfb</strong> 設置中改變。不過，這可能是你想提前做的事情，這樣你就可以避免向你的用户解釋如何改變協議的端口。</p><h3 id="查看和控制" tabindex="-1">查看和控制 <a class="header-anchor" href="#查看和控制" aria-label="Permalink to “查看和控制”">​</a></h3><p>當這個窗口打開時，你可以使用你喜歡的 VNC 客户端通過 VNC 登錄。KDE 有 <strong>krdc</strong>（表示 “KDE remote desktop client”）應用。在支持的計算機上，啓動它並向它提供目標 IP 地址。當你被提示輸入密碼時，輸入你正在連接的 <strong>krfb</strong> 會話中顯示的密碼。</p><p><img src="https://opensource.com/sites/default/files/kde-krdc-session.jpg" alt="Screen sharing with krdc" title="Screen sharing with krdc"></p><p>連接上後，你就可以看到你用户的屏幕，你可以在他們遵循你的指示時引導他們。如果他們在遵循你的指示方面有困難，那麼你可以控制他們的鼠標，並演示如何做某事。默認情況下，<strong>krfb</strong>（即他們正在運行的應用）在將控制權交給你之前會徵求他們的同意。</p><h3 id="幫助進行中" tabindex="-1">幫助進行中 <a class="header-anchor" href="#幫助進行中" aria-label="Permalink to “幫助進行中”">​</a></h3><p>能夠看到你的用户所看到的東西可以加速故障排除，減少支持電話雙方的挫折感。只要你事先為你的支持設置好網絡，<strong>krfb</strong> 和 <strong>krdc</strong> 的組合對於指導新用户完成 Linux 桌面發現之旅的 Linux 專業人士來説是很有價值的工具。</p><hr>',11)),o("p",null,[t[5]||(t[5]=e("via: ",-1)),s(r,{href:"https://opensource.com/article/22/2/screen-share-linux-kde"},{default:a(()=>[...t[4]||(t[4]=[e("https://opensource.com/article/22/2/screen-share-linux-kde",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=e("作者：",-1)),s(r,{href:"https://opensource.com/users/seth"},{default:a(()=>[...t[6]||(t[6]=[e("Seth Kenlon",-1)])]),_:1}),t[11]||(t[11]=e(" 選題：",-1)),s(r,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[7]||(t[7]=[e("lujun9972",-1)])]),_:1}),t[12]||(t[12]=e(" 譯者：",-1)),s(r,{href:"https://github.com/geekpi"},{default:a(()=>[...t[8]||(t[8]=[e("geekpi",-1)])]),_:1}),t[13]||(t[13]=e(" 校對：",-1)),s(r,{href:"https://github.com/wxy"},{default:a(()=>[...t[9]||(t[9]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[16]||(t[16]=e("本文由 ",-1)),s(r,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[14]||(t[14]=[e("LCTT",-1)])]),_:1}),t[17]||(t[17]=e(" 原創編譯，",-1)),s(r,{href:"https://linux.cn/"},{default:a(()=>[...t[15]||(t[15]=[e("Linux中國",-1)])]),_:1}),t[18]||(t[18]=e(" 榮譽推出",-1))])])}const P=l(m,[["render",u]]);export{D as __pageData,P as default};
